val name: String? = getUserName()

// ❌ Traditional approach
if (name != null) {
    println(name.toUpperCase())
}

// ✅ Using let
name?.let {
    println(it.toUpperCase())
}

// chaining operations
val result = "  hello kotlin  "
    .let { it.trim() }
    .let { it.capitalize() }
    .let { "Result: $it" }
println(result)  // "Result: Hello kotlin"
